/* src/styles.scss */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}
html,
body {
  height: 100%;
  background: #1e1e2e;
  overflow: hidden;
}
html:has(body.toast-window),
body.toast-window {
  background: transparent;
}
::-webkit-scrollbar {
  width: 4px;
}
::-webkit-scrollbar-track {
  background: transparent;
}
::-webkit-scrollbar-thumb {
  background: #313244;
  border-radius: 2px;
}
.ctx-menu {
  position: fixed;
  z-index: 70;
  min-width: 176px;
  max-width: 340px;
  padding: 4px;
  border-radius: 10px;
  isolation: isolate;
  border: 1px solid rgba(205, 214, 244, 0.13);
  box-shadow: 0 16px 36px -10px rgba(0, 0, 0, 0.75), 0 4px 12px -3px rgba(0, 0, 0, 0.5);
  font-family:
    "SF Mono",
    "Cascadia Code",
    "Consolas",
    monospace;
  font-size: 11px;
  -webkit-user-select: none;
  user-select: none;
  transform-origin: 0 0;
  animation: ctx-menu-in 0.12s ease-out;
}
.ctx-menu.anchored {
  transform-origin: 12px 0;
}
.ctx-menu.anchored.right {
  transform-origin: calc(100% - 12px) 0;
}
.ctx-menu::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  border-radius: inherit;
  pointer-events: none;
  background:
    linear-gradient(
      115deg,
      rgba(255, 255, 255, 0.055),
      transparent 42%,
      rgba(255, 255, 255, 0.025) 72%,
      transparent 90%),
    linear-gradient(rgba(22, 22, 34, 0.6), rgba(22, 22, 34, 0.7));
  -webkit-backdrop-filter: blur(16px) saturate(1.6);
  backdrop-filter: blur(16px) saturate(1.6);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.09);
}
.ctx-menu .ctx-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 10px;
  border-radius: 6px;
  color: #bac2de;
  cursor: pointer;
  white-space: nowrap;
}
.ctx-menu .ctx-item .ci-ic {
  width: 12px;
  height: 12px;
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #7f849c;
  font-size: 10.5px;
}
.ctx-menu .ctx-item .ci-ic svg {
  display: block;
}
.ctx-menu .ctx-item .ci-hint {
  margin-left: auto;
  padding-left: 18px;
  color: #6c7086;
  font-size: 10.5px;
}
.ctx-menu .ctx-item .ci-hint.stacked {
  display: inline-grid;
  justify-items: end;
}
.ctx-menu .ctx-item .ci-hint.stacked > span {
  grid-area: 1/1;
}
.ctx-menu .ctx-item .ci-go {
  color: #585b70;
  margin-left: 6px;
}
.ctx-menu .ctx-item .ci-go.lone {
  margin-left: auto;
  padding-left: 18px;
}
.ctx-menu .ctx-item:hover {
  background: rgba(205, 214, 244, 0.085);
  color: #e6ebfa;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.05);
}
.ctx-menu .ctx-item:hover .ci-ic {
  color: #cdd6f4;
}
.ctx-menu .ctx-item.danger {
  color: #f38ba8;
}
.ctx-menu .ctx-item.danger .ci-ic {
  color: #f38ba8;
}
.ctx-menu .ctx-item.danger:hover {
  background: rgba(243, 139, 168, 0.13);
  color: #f38ba8;
  box-shadow: none;
}
.ctx-menu .ctx-item.danger:hover .ci-ic {
  color: #f38ba8;
}
.ctx-menu .ctx-item.disabled {
  color: #585b70;
  cursor: default;
}
.ctx-menu .ctx-item.disabled .ci-ic,
.ctx-menu .ctx-item.disabled .ci-hint {
  color: #45475a;
}
.ctx-menu .ctx-item.disabled:hover {
  background: none;
  box-shadow: none;
  color: #585b70;
}
.ctx-menu .ctx-item.disabled:hover .ci-ic {
  color: #45475a;
}
.ctx-menu .ctx-item.busy {
  cursor: default;
}
.ctx-menu .ctx-item.busy:hover {
  background: none;
  box-shadow: none;
  color: #bac2de;
}
.ctx-menu .ctx-item.busy:hover .ci-ic {
  color: #7f849c;
}
.ctx-menu .ctx-item.busy .ci-hint,
.ctx-menu .ctx-item .ci-hint.busy {
  color: color-mix(in srgb, #f9e2af 82%, transparent);
  text-shadow: 0 0 3px rgba(249, 226, 175, 0.42), 0 1px 1px rgba(0, 0, 0, 0.25);
  animation: ctx-busy-breathe 1.6s ease-in-out infinite;
}
.ctx-menu .ctx-sep {
  height: 1px;
  margin: 3px 6px;
  background: rgba(205, 214, 244, 0.085);
}
.ctx-menu .ctx-branch {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 6px 10px;
  border-radius: 6px;
  cursor: pointer;
}
.ctx-menu .ctx-branch .ci-ic {
  width: 12px;
  height: 12px;
  flex-shrink: 0;
  margin-top: 1.5px;
  display: inline-flex;
  color: #7f849c;
  transition: color 0.15s ease;
}
.ctx-menu .ctx-branch .ci-ic svg {
  display: block;
}
.ctx-menu .ctx-branch .cb-name {
  flex: 1;
  min-width: 0;
  font-size: 10.5px;
  line-height: 1.45;
  color: #a6adc8;
  white-space: normal;
  text-wrap: balance;
  transition: color 0.15s ease;
}
.ctx-menu .ctx-branch:hover {
  background: rgba(205, 214, 244, 0.085);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.05);
}
.ctx-menu .ctx-branch:hover .cb-name,
.ctx-menu .ctx-branch.copied .cb-name {
  color: #e6ebfa;
}
.ctx-menu .ctx-branch:hover .ci-ic,
.ctx-menu .ctx-branch.copied .ci-ic {
  color: #cdd6f4;
}
@keyframes ctx-busy-breathe {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.3;
  }
}
@keyframes ctx-menu-in {
  0% {
    transform: scale(0.94);
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .ctx-menu {
    animation: none;
  }
  .ctx-menu .ctx-item.busy .ci-hint,
  .ctx-menu .ci-hint.busy {
    animation: none;
  }
}

